const htmlLessons: PathLesson[] = [
  { id: "html-document", order: 1, title: "HTML баримтын үндэс", duration: "20 мин", summary: "Browser хэрхэн HTML файлыг уншдагийг ойлгож, head ба body-ийн үүргийг ялгана.", keywords: [{ term: "<!doctype html>", meaning: "Баримтыг HTML5 гэж browser-д зарлана." }, { term: "<html lang>", meaning: "Баримтын үндсэн element ба хэлний код." }, { term: "<head>", meaning: "Metadata, title, холбоосуудын хэсэг." }, { term: "<body>", meaning: "Хэрэглэгчид харагдах агуулгын хэсэг." }, { term: "<meta charset>", meaning: "Тэмдэгтийн кодчиллыг UTF-8 болгоно." }, { term: "<title>", meaning: "Browser tab дээр харагдах гарчиг." }], code: "<!doctype html>\n<html lang=\"mn\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Миний анхны хуудас</title>\n  </head>\n  <body>\n    <p>Сайн байна уу.</p>\n  </body>\n</html>", challenge: { prompt: "Монгол хэлтэй HTML5 баримт үүсгээд browser tab-ийн гарчгийг `CodeCraft HTML` болго.", starter: "<!doctype html>\n<html>\n  <head>\n  </head>\n  <body>\n  </body>\n</html>", expected: ["lang=\"mn\"", "<meta charset=\"UTF-8\"", "<title>CodeCraft HTML</title>"], hint: "`lang` attribute нь `<html>` дээр, `meta` болон `title` нь `<head>` дотор байрлана.", xp: 20 }, checkpoint: { question: "Хэрэглэгчийн дэлгэцэд харагдах агуулга хаана ордог вэ?", choices: ["<head>", "<body>", "<title>"], answer: 1, explanation: "`body` нь page-ийн харагдах агуулгыг агуулна." } },
  { id: "html-semantic-text", order: 2, title: "Гарчиг ба semantic бүтэц", duration: "30 мин", summary: "Уншигдахуйц болон accessibility-д ээлтэй контентын бүтцийг semantic element-ээр зохион байгуулна.", keywords: [{ term: "<h1>–<h6>", meaning: "Гарчгийн шатлал." }, { term: "<p>", meaning: "Догол мөр." }, { term: "<header>", meaning: "Хуудас эсвэл section-ийн оршил." }, { term: "<nav>", meaning: "Навигацийн холбоосууд." }, { term: "<main>", meaning: "Давтагдашгүй гол агуулга." }, { term: "<section>", meaning: "Гарчигтай холбоотой агуулгын бүлэг." }, { term: "<article>", meaning: "Бие даан түгээгдэж болох контент." }, { term: "<footer>", meaning: "Төгсгөлийн мэдээлэл." }], code: "<header>\n  <h1>CodeCraft тэмдэглэл</h1>\n  <nav><a href=\"#lessons\">Хичээл</a></nav>\n</header>\n<main>\n  <section id=\"lessons\">\n    <h2>HTML-ийн эхлэл</h2>\n    <article><p>Semantic structure нь утгыг илэрхийлдэг.</p></article>\n  </section>\n</main>\n<footer>2026</footer>", challenge: { prompt: "`main` дотор `section` үүсгэж, түүнд `h2` ба `article` байрлуул. Article дотор нэг paragraph бич.", starter: "<main>\n  \n</main>", expected: ["<section", "<h2", "<article", "<p>"], hint: "Том агуулгыг section, бие даасан бичвэрийг article-аар ялга.", xp: 25 }, checkpoint: { question: "Хуудасны цорын ганц үндсэн агуулгыг аль element илэрхийлдэг вэ?", choices: ["<main>", "<div>", "<span>"], answer: 0, explanation: "`main` нь document-ийн гол, давтагдашгүй агуулгыг тэмдэглэнэ." } },
  { id: "html-links-media", order: 3, title: "Холбоос, зураг, media", duration: "28 мин", summary: "Хэрэглэгчийг чиглүүлэх холбоос болон утгатай media контент оруулна.", keywords: [{ term: "<a href>", meaning: "Холбоос үүсгэх." }, { term: "target=\"_blank\"", meaning: "Холбоосыг шинэ tab-д нээх." }, { term: "rel=\"noreferrer\"", meaning: "Гадаад tab нээхэд аюулгүй байдлын нэмэлт attribute." }, { term: "<img src alt>", meaning: "Зураг ба текстэн тайлбар." }, { term: "<figure>", meaning: "Зураг/diagram шиг бие даасан media." }, { term: "<figcaption>", meaning: "Figure-ийн тайлбар." }, { term: "<audio>, <video>", meaning: "Media тоглуулах element." }], code: "<figure>\n  <img src=\"lesson-map.png\" alt=\"HTML хичээлийн маршрут\" />\n  <figcaption>Эхний долоон хоногийн зам.</figcaption>\n</figure>\n<a href=\"https://developer.mozilla.org\" target=\"_blank\" rel=\"noreferrer\">MDN нээх</a>", challenge: { prompt: "`figure` дотор alt-той зураг, figcaption нэм. Дараа нь MDN рүү шинэ tab-д нээгдэх аюулгүй холбоос бич.", starter: "<figure>\n  \n</figure>\n\n<a>MDN</a>", expected: ["<img", "alt=", "<figcaption>", "href=", "target=\"_blank\""], hint: "Зураг бүр утгатай `alt`-тай байх ёстой.", xp: 25 }, checkpoint: { question: "Зургийн утгыг screen reader-д дамжуулах гол attribute аль нь вэ?", choices: ["src", "alt", "width"], answer: 1, explanation: "`alt` нь зургийн текстэн хувилбар юм." } },
  { id: "html-lists-tables", order: 4, title: "Жагсаалт ба хүснэгт", duration: "25 мин", summary: "Дараалалтай/дараалалгүй өгөгдөл болон мөр-багана бүтэцтэй мэдээллийг зөв тэмдэглэнэ.", keywords: [{ term: "<ul>, <ol>", meaning: "Дараалалгүй, дараалалтай жагсаалт." }, { term: "<li>", meaning: "Жагсаалтын нэг item." }, { term: "<dl>, <dt>, <dd>", meaning: "Нэр томьёо, тайлбарын жагсаалт." }, { term: "<table>", meaning: "Хүснэгтийн контейнер." }, { term: "<thead>, <tbody>", meaning: "Хүснэгтийн толгой, үндсэн бие." }, { term: "<tr>, <th>, <td>", meaning: "Мөр, толгой нүд, өгөгдлийн нүд." }, { term: "scope", meaning: "Table header ямар нүдэнд хамаарахыг заана." }], code: "<table>\n  <thead><tr><th scope=\"col\">Хэл</th><th scope=\"col\">Хичээл</th></tr></thead>\n  <tbody><tr><td>HTML</td><td>6</td></tr></tbody>\n</table>", challenge: { prompt: "HTML ба CSS гэсэн хоёр мөртэй, Хэл ба Хичээл гэсэн хоёр баганатай accessible хүснэгт үүсгэ.", starter: "<table>\n  \n</table>", expected: ["<thead>", "<tbody>", "<th", "scope=\"col\"", "<td>"], hint: "Column header дээр `scope=\"col\"` нэмэхийг санаарай.", xp: 25 }, checkpoint: { question: "Хүснэгтийн толгой нүдийг аль tag илэрхийлдэг вэ?", choices: ["<td>", "<th>", "<tr>"], answer: 1, explanation: "`th` нь хүснэгтийн header cell-д ашиглагдана." } },
  { id: "html-forms", order: 5, title: "Form ба хэрэглэгчийн input", duration: "35 мин", summary: "Мэдээлэл цуглуулах form-ыг label, type, validation attribute-тайгаар бүтээнэ.", keywords: [{ term: "<form>", meaning: "Input-уудыг нэг submit урсгалд багцална." }, { term: "<label for>", meaning: "Input-ын нэр ба accessibility холболт." }, { term: "<input type>", meaning: "text, email, password, checkbox зэрэг input төрөл." }, { term: "<textarea>", meaning: "Олон мөрт текст." }, { term: "<select>, <option>", meaning: "Сонголтын жагсаалт." }, { term: "required", meaning: "Заавал бөглөх validation." }, { term: "<button type=\"submit\">", meaning: "Form submit хийх товч." }], code: "<form>\n  <label for=\"email\">Имэйл</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required />\n  <label for=\"note\">Тайлбар</label>\n  <textarea id=\"note\" name=\"note\"></textarea>\n  <button type=\"submit\">Илгээх</button>\n</form>", challenge: { prompt: "Email болон тайлбар авдаг form хий. Label нь input/textarea-тай `for` ба `id`-аар холбогдсон байх ёстой.", starter: "<form>\n  \n</form>", expected: ["<label", "for=", "type=\"email\"", "required", "<textarea", "type=\"submit\""], hint: "Input бүр label-тай бол keyboard болон screen reader хэрэглэгчдэд ойлгомжтой.", xp: 30 }, checkpoint: { question: "Form дээр заавал бөглөх талбарын attribute аль нь вэ?", choices: ["required", "checked", "hidden"], answer: 0, explanation: "`required` нь submit-ийн өмнө browser validation ажиллуулна." } },
  { id: "html-accessibility-project", order: 6, title: "Metadata, accessibility ба mini project", duration: "40 мин", summary: "SEO, accessibility болон semantic бүтцээ нэг мини хичээлийн хуудас болгон нэгтгэнэ.", keywords: [{ term: "meta name=\"viewport\"", meaning: "Mobile viewport-ийг зөв тохируулна." }, { term: "meta name=\"description\"", meaning: "Хайлтын системд товч тайлбар өгнө." }, { term: "aria-label", meaning: "Харагдах текстгүй control-д нэр өгнө." }, { term: "<button>", meaning: "Үйлдэл хийх control; navigation-д a биш button хэрэглэнэ." }, { term: "<label>", meaning: "Form field-ийн ил тод нэр." }, { term: "alt", meaning: "Зургийн зориулалтын текстэн тайлбар." }], code: "<head>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"description\" content=\"HTML сурах мини хичээл\" />\n</head>\n<body>\n  <main aria-label=\"HTML хичээлийн агуулга\">...</main>\n</body>", challenge: { prompt: "Өмнөх 5 хичээлийн element-үүдийг ашиглан өөрийн 'HTML cheat sheet' хуудасны semantic outline бүтээ. Metadata, main, section, list, холбоос, form оруул.", starter: "<!doctype html>\n<html lang=\"mn\">\n  <head>\n  </head>\n  <body>\n  </body>\n</html>", expected: ["name=\"viewport\"", "<main", "<section", "<ul", "<a", "<form"], hint: "Эхлээд outline-аа semantic element-ээр, дараа нь жижиг content-оор дүүргэ.", xp: 50 }, checkpoint: { question: "Navigation хийх элемент аль нь вэ?", choices: ["<button>", "<a href>", "<div>"], answer: 1, explanation: "Өөр URL эсвэл hash руу шилжихэд anchor element хэрэглэнэ." } },
];

const cssLessons: PathLesson[] = [
  { id: "css-selectors-cascade", order: 1, title: "Selector, cascade, specificity", duration: "28 мин", summary: "CSS аль element-д үйлчлэх, зөрчилдөх rule-ийг browser хэрхэн сонгодгийг ойлгоно.", keywords: [{ term: "type selector", meaning: "`p {}` шиг tag-аар сонгоно." }, { term: ".class", meaning: "Давтан ашиглах class selector." }, { term: "#id", meaning: "Нэг онцгой element-ийн selector." }, { term: "descendant", meaning: "`.card p` шиг доторх element сонгоно." }, { term: ":hover", meaning: "Pointer hover state." }, { term: "specificity", meaning: "Зөрчилдөх rule-ийн давуу эрх." }, { term: "inherit", meaning: "Эцэг element-ээс өвлөгдөх шинж." }], code: ".lesson-card { color: #173b39; }\n.lesson-card p { color: #52666c; }\n.lesson-card a:hover { color: #0f766e; }", challenge: { prompt: "`.lesson-card` class-д border өг. Доторх paragraph-г өөр өнгөтэй, link hover үед ногоон болго.", starter: ".lesson-card {\n}\n", expected: [".lesson-card", "border", ".lesson-card p", ":hover"], hint: "Element-ийн доторх paragraph-г `.lesson-card p` гэж сонгоно.", xp: 20 }, checkpoint: { question: "`.card` selector ямар attribute дээр тулгуурладаг вэ?", choices: ["class", "id", "name"], answer: 0, explanation: "Цэгтэй selector нь class attribute-г сонгодог." } },
  { id: "css-values-box", order: 2, title: "Өнгө, unit, box model", duration: "35 мин", summary: "Content, padding, border, margin-ийн ялгаа болон relative хэмжээсийг дадлагаар ойлгоно.", keywords: [{ term: "color", meaning: "Текстийн өнгө." }, { term: "background", meaning: "Element-ийн дэвсгэр." }, { term: "px, rem, %, vw", meaning: "Түгээмэл хэмжээсийн unit." }, { term: "padding", meaning: "Content ба border-ын доторх зай." }, { term: "border", meaning: "Element-ийн хүрээ." }, { term: "margin", meaning: "Element-ийн гаднах зай." }, { term: "box-sizing", meaning: "Width/height тооцоолох горим." }], code: ".card {\n  box-sizing: border-box;\n  max-width: 42rem;\n  margin: 2rem auto;\n  padding: 1.5rem;\n  border: 1px solid #d8ded9;\n  background: #fffdf7;\n}", challenge: { prompt: "`.challenge` box-д max-width, auto margin, padding, border, background өг.", starter: ".challenge {\n}\n", expected: ["max-width", "margin", "padding", "border", "background"], hint: "Төвлөрүүлэхэд `margin: 0 auto` ашигла.", xp: 25 }, checkpoint: { question: "Content ба border-ын хоорондох зай аль нь вэ?", choices: ["margin", "padding", "gap"], answer: 1, explanation: "Padding нь element-ийн дотоод зай юм." } },
  { id: "css-typography", order: 3, title: "Typography ба visual hierarchy", duration: "26 мин", summary: "Уншихад амар текстийн хэмжээ, жин, мөр хоорондын зай, contrast-ийг тохируулна.", keywords: [{ term: "font-family", meaning: "Font stack сонгоно." }, { term: "font-size", meaning: "Текстийн хэмжээ." }, { term: "font-weight", meaning: "Текстийн жин." }, { term: "line-height", meaning: "Мөр хоорондын зай." }, { term: "letter-spacing", meaning: "Үсэг хоорондын зай." }, { term: "text-align", meaning: "Текстийн тэгшилгээ." }, { term: "contrast", meaning: "Text/background ялгарал." }], code: ".lesson-title {\n  font-family: Georgia, serif;\n  font-size: clamp(2rem, 5vw, 4rem);\n  line-height: .96;\n  letter-spacing: -.05em;\n}", challenge: { prompt: "`.lesson-title`-д serif font stack, responsive font-size, compact line-height тохируул.", starter: ".lesson-title {\n}\n", expected: ["font-family", "font-size", "line-height"], hint: "`clamp(min, fluid, max)` нь responsive текстэд тохиромжтой.", xp: 20 }, checkpoint: { question: "Мөр хоорондын зайг аль property удирдах вэ?", choices: ["line-height", "font-weight", "opacity"], answer: 0, explanation: "`line-height` нь line box-ийн өндрийг удирдана." } },
  { id: "css-flex", order: 4, title: "Flexbox layout", duration: "35 мин", summary: "Нэг тэнхлэгт элементүүдийг байрлуулах, зай хуваарилах, responsive row/column болгоно.", keywords: [{ term: "display: flex", meaning: "Flex formatting context нээнэ." }, { term: "flex-direction", meaning: "Main axis-ийн чиглэл." }, { term: "justify-content", meaning: "Main axis дагуу байрлуулна." }, { term: "align-items", meaning: "Cross axis дагуу тэгшилнэ." }, { term: "gap", meaning: "Flex item хоорондын зай." }, { term: "flex-wrap", meaning: "Зай хүрэхгүй үед мөр шилжүүлнэ." }, { term: "flex: 1", meaning: "Чөлөөт зайг эзлэх өсөлтийн shorthand." }], code: ".lesson-actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}", challenge: { prompt: "Title ба button-ыг нэг мөрөнд зайтай байрлуулах `.actions` flex layout бич. Mobile дээр wrap хийх боломжоор ханга.", starter: ".actions {\n}\n", expected: ["display: flex", "justify-content", "gap", "flex-wrap"], hint: "`space-between` нь эхлэл ба төгсгөл рүү item-уудыг тараана.", xp: 30 }, checkpoint: { question: "Flex item хоорондын тогтмол зайд аль property хамгийн тохиромжтой вэ?", choices: ["gap", "padding", "float"], answer: 0, explanation: "`gap` нь flex болон grid item хоорондын зайг удирдана." } },
  { id: "css-grid-responsive", order: 5, title: "Grid ба responsive design", duration: "40 мин", summary: "Хоёр хэмжээст layout болон жижиг дэлгэцийн breakpoint-ийг бүтээнэ.", keywords: [{ term: "display: grid", meaning: "Grid layout нээнэ." }, { term: "grid-template-columns", meaning: "Баганын track тодорхойлно." }, { term: "minmax()", meaning: "Track-ийн minimum/maximum хэмжээс." }, { term: "repeat()", meaning: "Давтагдах grid track." }, { term: "@media", meaning: "Viewport зэрэг нөхцөлт rule." }, { term: "max-width", meaning: "Mobile-first breakpoint-д ашиглана." }, { term: "clamp()", meaning: "Fluid хэмжээ сонгоно." }], code: ".module-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 1rem;\n}\n@media (max-width: 720px) {\n  .module-grid { grid-template-columns: 1fr; }\n}", challenge: { prompt: "Desktop дээр 3 багана, 720px-ээс доош 1 багана болох `.module-grid` бич.", starter: ".module-grid {\n}\n", expected: ["display: grid", "grid-template-columns", "@media", "max-width: 720px"], hint: "Media query дотор `.module-grid`-ийн columns-ыг дахин тодорхойл.", xp: 35 }, checkpoint: { question: "Хоёр хэмжээст мөр, баганатай layout-д аль систем тохиромжтой вэ?", choices: ["Grid", "Flexbox", "inline"], answer: 0, explanation: "CSS Grid нь rows, columns-ыг хамтад нь удирдана." } },
  { id: "css-motion-project", order: 6, title: "Transition, animation ба responsive project", duration: "42 мин", summary: "Interactive state, motion, reduced-motion зэргийг хамарсан responsive card project хийнэ.", keywords: [{ term: "transition", meaning: "State хоорондын зөөлөн шилжилт." }, { term: "transform", meaning: "Move/scale/rotate; performance-д ээлтэй." }, { term: "opacity", meaning: "Тунгалагшил." }, { term: "@keyframes", meaning: "Animation frame sequence." }, { term: "animation", meaning: "Keyframe animation ашиглана." }, { term: "prefers-reduced-motion", meaning: "Motion багасгах user preference." }, { term: ":focus-visible", meaning: "Keyboard focus-ийн харагдах төлөв." }], code: ".card { transition: transform 180ms cubic-bezier(.23,1,.32,1); }\n.card:hover { transform: translateY(-4px); }\n.card:focus-visible { outline: 3px solid #0f766e; }\n@media (prefers-reduced-motion: reduce) { .card { transition: none; } }", challenge: { prompt: "Hover үед дээш хөдөлдөг, keyboard focus нь тод харагддаг, reduced motion хүнд animation-гүй card rule бич.", starter: ".card {\n}\n", expected: ["transition", ":hover", "transform", ":focus-visible", "prefers-reduced-motion"], hint: "User-ийн accessibility preference-г media query-ээр хүндэл.", xp: 50 }, checkpoint: { question: "Motion багасгах user preference-ийг ямар media query шалгах вэ?", choices: ["prefers-reduced-motion", "orientation", "hover"], answer: 0, explanation: "`prefers-reduced-motion` нь хөдөлгөөн багасгах preference-г илэрхийлнэ." } },
];

const javascriptLessons: PathLesson[] = [
  { id: "js-values", order: 1, title: "Хувьсагч ба өгөгдлийн төрөл", duration: "28 мин", summary: "JavaScript-ийн value, const/let, string/number/boolean/null/undefined-ийн үндсийг туршина.", keywords: [{ term: "const", meaning: "Дахин оноохгүй binding." }, { term: "let", meaning: "Дахин оноож болох binding." }, { term: "string", meaning: "Текст утга." }, { term: "number", meaning: "Тоон утга." }, { term: "boolean", meaning: "true/false." }, { term: "null", meaning: "Зориуд хоосон утга." }, { term: "typeof", meaning: "Value-ийн төрлийг шалгана." }], code: "const course = \"JavaScript\";\nlet xp = 0;\nconst unlocked = xp > 10;\nconsole.log(typeof course, unlocked);", challenge: { prompt: "`course` нэртэй const string, `xp` нэртэй let number, `isReady` нэртэй boolean үүсгээд console.log хий.", starter: "", expected: ["const course", "let xp", "const isReady", "console.log"], hint: "Дахин өөрчлөх XP-д `let`, тогтмол course нэрэнд `const` хэрэглэ.", xp: 20 }, checkpoint: { question: "Дахин оноохгүй binding-д аль keyword тохирох вэ?", choices: ["const", "let", "var"], answer: 0, explanation: "`const` binding-ийг дахин оноохыг хориглодог." } },
  { id: "js-control-flow", order: 2, title: "Operator ба control flow", duration: "35 мин", summary: "Comparison, logical operator, if/else, switch, loop-оор шийдвэрийн логик бичнэ.", keywords: [{ term: "===", meaning: "Type болон value хатуу тэнцүү эсэх." }, { term: "&&, ||, !", meaning: "Logical operator." }, { term: "if / else", meaning: "Нөхцөлт салаалалт." }, { term: "switch", meaning: "Олон салаат сонголт." }, { term: "for", meaning: "Тоолууртай давталт." }, { term: "for...of", meaning: "Iterable item-уудаар давтах." }, { term: "break / continue", meaning: "Давталтын урсгал удирдах." }], code: "const score = 80;\nif (score >= 70) {\n  console.log(\"Challenge нээгдлээ\");\n} else {\n  console.log(\"Дахин оролдоорой\");\n}", challenge: { prompt: "`score` 70-аас их буюу тэнцүү бол 'pass', бусад үед 'retry' хэвлэдэг if/else бич.", starter: "const score = 72;\n\n", expected: ["if", "score >= 70", "else", "console.log"], hint: "Нөхцөлийг `if (...) {}` дотор бичиж, эсрэг хувилбарт `else` ашигла.", xp: 25 }, checkpoint: { question: "Type болон value хоёуланг нь шалгах оператор аль нь вэ?", choices: ["==", "===", "="], answer: 1, explanation: "`===` нь strict equality шалгана." } },
  { id: "js-functions-arrays", order: 3, title: "Function, array, scope", duration: "38 мин", summary: "Давтагдах логикийг function болгон задлаж, array data-г map/filter ашиглан хувиргана.", keywords: [{ term: "function", meaning: "Named reusable block." }, { term: "return", meaning: "Function-ийн үр дүн буцаана." }, { term: "parameter", meaning: "Function input-ын нэр." }, { term: "scope", meaning: "Хувьсагчийн харагдах муж." }, { term: "array", meaning: "Дараалсан value collection." }, { term: "map()", meaning: "Array item бүрийг хувиргана." }, { term: "filter()", meaning: "Нөхцөлд тохирох item-уудыг шүүнэ." }], code: "const lessons = [\"HTML\", \"CSS\", \"JS\"];\nfunction badge(name) { return `✓ ${name}`; }\nconsole.log(lessons.map(badge));", challenge: { prompt: "`formatLesson(name)` function бичиж `Lesson: ${name}` буцаа. Дараа нь lessons array дээр map ашигла.", starter: "const lessons = [\"HTML\", \"CSS\"];\n\n", expected: ["function formatLesson", "return", ".map("], hint: "Function-ийг map-д callback болгон өгөх эсвэл arrow function ашиглаж болно.", xp: 30 }, checkpoint: { question: "Function-ийн үр дүнг caller руу буцаах keyword аль нь вэ?", choices: ["return", "yield", "break"], answer: 0, explanation: "`return` нь function-ийг дуусгаж value буцаадаг." } },
  { id: "js-objects-modules", order: 4, title: "Object, destructuring, module", duration: "35 мин", summary: "Холбоотой data-г object-д хадгалж, modern module-аар кодоо хуваана.", keywords: [{ term: "object", meaning: "Key-value data structure." }, { term: "property", meaning: "Object-ийн key/value." }, { term: "destructuring", meaning: "Object/array-аас value задлах." }, { term: "?.", meaning: "Optional chaining." }, { term: "export", meaning: "Module-оос value гаргана." }, { term: "import", meaning: "Өөр module-ийн value авна." }, { term: "default", meaning: "Module-ийн default export." }], code: "export const lesson = { title: \"DOM\", xp: 35 };\nconst { title, xp } = lesson;\nconsole.log(`${title}: ${xp}`);", challenge: { prompt: "`learner` object-д name, level key хий. Destructuring ашиглан хоёр value-ийг авч console.log бич.", starter: "const learner = {\n  name: \"Naraa\",\n  level: 2,\n};\n", expected: ["const { name, level }", "console.log"], hint: "Object-ийн key нэртэй ижил variable хэрэгтэй бол `{ name, level }` гэж задлана.", xp: 25 }, checkpoint: { question: "Object-оос `name` value-г задлах modern syntax аль нь вэ?", choices: ["const { name } = user", "const name in user", "user -> name"], answer: 0, explanation: "Destructuring syntax нь object-ийн property-г variable болгож гаргана." } },
  { id: "js-dom-events", order: 5, title: "DOM, event, хэрэглэгчийн үйлдэл", duration: "45 мин", summary: "Document-оос element сонгож, event listener-ээр UI-г өөрчилнө.", keywords: [{ term: "document.querySelector", meaning: "Эхний matching DOM element сонгоно." }, { term: "querySelectorAll", meaning: "Бүх matching element сонгоно." }, { term: "addEventListener", meaning: "Event handler бүртгэнэ." }, { term: "click", meaning: "Pointer/keyboard click event." }, { term: "event.preventDefault", meaning: "Default browser action зогсооно." }, { term: "textContent", meaning: "Аюулгүй plain text өөрчилнө." }, { term: "classList", meaning: "CSS class add/remove/toggle." }], code: "const button = document.querySelector(\"#start\");\nconst output = document.querySelector(\"#status\");\nbutton.addEventListener(\"click\", () => {\n  output.textContent = \"Challenge эхэллээ\";\n});", challenge: { prompt: "`#check` button click хийхэд `#result` element-ийн textContent-ийг 'Зөв!' болго.", starter: "const button = document.querySelector(\"#check\");\nconst result = document.querySelector(\"#result\");\n", expected: ["addEventListener", "click", "result.textContent"], hint: "Callback function event болох үед л ажиллана.", xp: 35 }, checkpoint: { question: "DOM event handler бүртгэх method аль нь вэ?", choices: ["addEventListener", "querySelector", "append"], answer: 0, explanation: "`addEventListener` нь event type ба callback авдаг." } },
  { id: "js-async-errors", order: 6, title: "Async, fetch, error handling", duration: "45 мин", summary: "Network хариу хүлээх async flow, JSON, try/catch, finally-г ойлгож жижиг data loader бичнэ.", keywords: [{ term: "async", meaning: "Promise буцаах function-г тэмдэглэнэ." }, { term: "await", meaning: "Promise resolve болохыг хүлээнэ." }, { term: "fetch", meaning: "HTTP request эхлүүлнэ." }, { term: "Response.ok", meaning: "HTTP response амжилттай эсэх." }, { term: "json()", meaning: "Response body-г JSON болгон уншина." }, { term: "try/catch", meaning: "Error барих." }, { term: "finally", meaning: "Амжилт/алдаанаас үл хамааран ажиллах block." }], code: "async function loadLesson() {\n  try {\n    const response = await fetch(\"/api/lesson\");\n    if (!response.ok) throw new Error(\"Load failed\");\n    return await response.json();\n  } catch (error) {\n    console.error(error);\n  }\n}", challenge: { prompt: "Async function дотор fetch дуудаж, response.ok false бол Error шид. Error-ийг catch дотор console.error хийнэ.", starter: "async function load() {\n  \n}\n", expected: ["await fetch", "response.ok", "throw new Error", "catch"], hint: "Network алдаа болон HTTP алдааг хоёуланг нь handle хий.", xp: 50 }, checkpoint: { question: "Promise resolve болохыг function дотор хүлээх keyword аль нь вэ?", choices: ["await", "yield", "pause"], answer: 0, explanation: "`await` нь async function дотор Promise-ийн үр дүнг хүлээнэ." } },
];

const pythonLessons: PathLesson[] = [
  { id: "py-syntax-values", order: 1, title: "Python syntax, variable, print", duration: "25 мин", summary: "Indentation, variable, үндсэн data type болон print function-оор кодын эхлэлийг тавина.", keywords: [{ term: "print()", meaning: "Console-д output хэвлэнэ." }, { term: "=", meaning: "Variable-д value онооно." }, { term: "str", meaning: "Text type." }, { term: "int, float", meaning: "Integer, decimal number." }, { term: "bool", meaning: "True/False." }, { term: "None", meaning: "Утга байхгүйг илэрхийлнэ." }, { term: "# comment", meaning: "Кодын тайлбар." }], code: "course = \"Python\"\nlevel = 1\nready = True\nprint(f\"{course}: level {level}, ready={ready}\")", challenge: { prompt: "name, level, is_ready гэсэн variable үүсгэж f-string ашиглан нэг мөр output хэвлэ.", starter: "", expected: ["name =", "level =", "is_ready =", "print(f"], hint: "Python string interpolation-д `f\"...{name}...\"` хэлбэр ашигла.", xp: 20 }, checkpoint: { question: "Python code block-ийг юу тодорхойлдог вэ?", choices: ["Догол мөр", "Хаалт", "Таслал"], answer: 0, explanation: "Python нь indentation-аар block-ийн хилийг тогтоодог." } },
  { id: "py-collections", order: 2, title: "String, list, tuple, set, dict", duration: "40 мин", summary: "Өгөгдлийн бүтэц бүрийг ямар асуудалд сонгохоо жишээгээр ойлгоно.", keywords: [{ term: "list []", meaning: "Дараалалтай, өөрчлөгдөх collection." }, { term: "tuple ()", meaning: "Дараалалтай, өөрчлөгдөхгүй collection." }, { term: "set {}", meaning: "Давхардалгүй unique value." }, { term: "dict {key: value}", meaning: "Key-value mapping." }, { term: "append()", meaning: "List-ийн төгсгөлд item нэмнэ." }, { term: "len()", meaning: "Collection-ийн урт." }, { term: "in", meaning: "Агуулж буй эсэхийг шалгана." }], code: "skills = [\"HTML\", \"CSS\"]\nlearner = {\"name\": \"Naraa\", \"xp\": 80}\nskills.append(\"Python\")\nprint(learner[\"name\"], len(skills))", challenge: { prompt: "`topics` list, `profile` dict үүсгэ. List-д нэг шинэ item append хийгээд dict-ээс name хэвлэ.", starter: "", expected: ["topics = [", "profile = {", ".append(", "profile[\"name\"]"], hint: "Dictionary value-г key-ээр нь дөрвөлжин хаалтаар авна.", xp: 25 }, checkpoint: { question: "Key-value pair хадгалах Python бүтэц аль нь вэ?", choices: ["dict", "list", "tuple"], answer: 0, explanation: "Dictionary нь key-аар value рүү ханддаг." } },
  { id: "py-control-flow", order: 3, title: "if, for, while, range", duration: "38 мин", summary: "Шийдвэр ба давталтаар program flow-ийг удирдана.", keywords: [{ term: "if / elif / else", meaning: "Нөхцөлт салаалалт." }, { term: "for", meaning: "Iterable item-уудаар давтах." }, { term: "while", meaning: "Нөхцөл үнэн байх хугацаанд давтах." }, { term: "range()", meaning: "Тоон дараалал үүсгэнэ." }, { term: "break", meaning: "Давталтаас шууд гарна." }, { term: "continue", meaning: "Тухайн iteration-ийг алгасна." }, { term: "pass", meaning: "Хоосон block-ийн placeholder." }], code: "xp = 45\nif xp >= 50:\n    print(\"Level up\")\nelse:\n    print(\"Дахиад challenge хий\")\n\nfor step in range(1, 4):\n    print(f\"Алхам {step}\")", challenge: { prompt: "score 70-аас их бол outcome-д 'pass' оноож, түүнийг хэвлэ. Дараа нь range ашиглан 1-3 хүртэл хэвлэ.", starter: "score = 72\n\nif score >= 70:\n    outcome = \"pass\"\nelse:\n    outcome = \"retry\"\n\nprint(outcome)\nfor step in range(1, 4):\n    print(step)", expected: ["if score >= 70", "else:", "for", "range("], hint: "Colon-ийн дараах мөр заавал доголтой эхэлнэ. `outcome`-ийг condition-ийн хоёр салаанд онооно.", xp: 30 }, checkpoint: { question: "List item бүрээр давтахад аль statement тохиромжтой вэ?", choices: ["for", "match", "def"], answer: 0, explanation: "`for` нь iterable-ийн item-уудаар дарааллаар явна." } },
  { id: "py-functions", order: 4, title: "Function, parameter, comprehension", duration: "40 мин", summary: "Function-оор логикоо дахин ашиглаж, list comprehension-оор data transformation хийнэ.", keywords: [{ term: "def", meaning: "Function тодорхойлно." }, { term: "return", meaning: "Function-оос value буцаана." }, { term: "parameter", meaning: "Function input." }, { term: "default argument", meaning: "Default value-той parameter." }, { term: "*args, **kwargs", meaning: "Олон аргумент цуглуулах." }, { term: "lambda", meaning: "Жижиг anonymous function." }, { term: "comprehension", meaning: "Collection-ийг compact байдлаар үүсгэнэ." }], code: "def badge(name, level=1):\n    return f\"{name} · L{level}\"\n\nlevels = [1, 2, 3]\nlabels = [badge(\"Learner\", level) for level in levels]\nprint(labels)", challenge: { prompt: "`is_passed(score)` function бичиж score >= 70 boolean буцаа. Дараа нь list comprehension-оор тэнцсэн score-уудыг шүү.", starter: "scores = [40, 70, 88, 55]\n\n", expected: ["def is_passed", "return", "for", "if"], hint: "Comprehension: `[value for value in values if condition]`.", xp: 35 }, checkpoint: { question: "Python function эхлүүлэх keyword аль нь вэ?", choices: ["def", "function", "func"], answer: 0, explanation: "`def` keyword нь function definition эхлүүлдэг." } },
  { id: "py-modules-files", order: 5, title: "Module, file, JSON", duration: "42 мин", summary: "Кодоо module болгон хувааж, file болон JSON data уншиж бичих үндсийг сурна.", keywords: [{ term: "import", meaning: "Module оруулна." }, { term: "from ... import", meaning: "Тодорхой нэр import хийнэ." }, { term: "__name__", meaning: "Module script болж ажиллаж буй эсэх." }, { term: "with open", meaning: "File-ийг аюулгүй нээж хаана." }, { term: "read(), write()", meaning: "File input/output." }, { term: "json.load", meaning: "JSON file-ийг Python object болгоно." }, { term: "json.dump", meaning: "Python object-ийг JSON болгон бичнэ." }], code: "import json\n\nwith open(\"progress.json\", encoding=\"utf-8\") as file:\n    progress = json.load(file)\nprint(progress)", challenge: { prompt: "Sandbox-д бэлэн байгаа `notes.txt` файлыг `with open` ашиглан UTF-8 encoding-оор уншаад `content` variable-д хадгал.", starter: "with open(\"notes.txt\", encoding=\"utf-8\") as file:\n    content = file.read()\n\nprint(content)", expected: ["with open(", "encoding=\"utf-8\"", "as file", ".read("], hint: "`with` block дуусахад file автоматаар хаагдана. `content = file.read()` гэсэн бодит үр дүнг validator шалгана.", xp: 35 }, checkpoint: { question: "File-ийг найдвартай хаах контекст manager syntax аль нь вэ?", choices: ["with open", "open forever", "file.start"], answer: 0, explanation: "`with open(...) as file:` нь resource cleanup-г баталгаажуулна." } },
  { id: "py-errors-classes", order: 6, title: "Exception, class, mini project", duration: "50 мин", summary: "Error handling, class-ийн үндэс болон суралцагчийн XP tracker mini project-оор Python замаа баталгаажуулна.", keywords: [{ term: "try / except", meaning: "Exception барих." }, { term: "raise", meaning: "Exception зориуд үүсгэх." }, { term: "finally", meaning: "Ямар ч нөхцөлд ажиллах cleanup." }, { term: "class", meaning: "Object blueprint." }, { term: "__init__", meaning: "Object initialize хийх method." }, { term: "self", meaning: "Одоогийн object reference." }, { term: "isinstance", meaning: "Object-ийн type шалгах." }], code: "class Learner:\n    def __init__(self, name):\n        self.name = name\n        self.xp = 0\n\n    def add_xp(self, amount):\n        if amount < 0:\n            raise ValueError(\"XP сөрөг байж болохгүй\")\n        self.xp += amount\n\ntry:\n    learner = Learner(\"Naraa\")\n    learner.add_xp(25)\nexcept ValueError as error:\n    print(error)", challenge: { prompt: "`Learner` class хийж, name болон xp property оноо. `add_xp` method нь xp-г нэмдэг байх ёстой.", starter: "class Learner:\n    \n", expected: ["class Learner", "def __init__", "self.name", "def add_xp", "self.xp +="], hint: "Instance property бүрийг `self.`-ээр хадгална.", xp: 55 }, checkpoint: { question: "Exception барих Python block аль нь вэ?", choices: ["try/except", "if/else", "for/in"], answer: 0, explanation: "Error үүсч болзошгүй code-ийг try, handler-ийг except-д бичнэ." } },
];

