function atomicToLesson(language: LanguageId, unit: AtomicLesson, order: number): PathLesson {
  const debugStarter = language === "css" && unit.quest === "debug" ? unit.starter.replace(unit.expected[0]?.split("::")[1] ?? "", `${unit.expected[0]?.split("::")[1] ?? ""}-broken`) : language === "html" && unit.quest === "debug" && unit.starter.includes("alt=") ? unit.starter.replace("alt=", "data-alt=") : unit.starter;
  const difficulty = difficultyGuidance(order);
  return { id: unit.id, order, title: `${unit.title} · ${difficulty.label}`, duration: "12–18 мин", summary: unit.meaning, keywords: [{ term: unit.term, meaning: unit.meaning }], code: unit.code, challenge: { prompt: `${unit.term} ойлголтын ${difficulty.label.toLowerCase()} шатны code quest. ${difficulty.guidance}`, starter: debugStarter, expected: unit.expected, hint: `Эхлээд ${unit.term} ямар үүрэгтэйг жишээнээс харж, дараа нь өөрийн кодоо бүтээнэ үү.`, xp: unit.quest === "timed" ? 30 : 20, kind: unit.quest, prediction: unit.quest === "predict" ? { prompt: `Кодыг шалгахаас өмнө энэ lesson-ийн гол tag/keyword-ийг яг бичнэ үү.`, answer: unit.term } : undefined }, checkpoint: { question: `${unit.term} ямар зориулалттай вэ?`, choices: [unit.meaning, "Зөвхөн зураг оруулдаг element/property.", "Browser-ийг хаадаг command."], answer: 0, explanation: unit.meaning }, quiz: buildLessonQuiz({ lessonId: unit.id, language, term: unit.term, meaning: unit.meaning, code: unit.code, starter: debugStarter, expected: unit.expected }) };
}

const htmlDetailed = htmlAtomic.map((unit, index) => atomicToLesson("html", unit, index + 1));
const cssDetailed = cssAtomic.map((unit, index) => atomicToLesson("css", unit, index + 1));
const javascriptDetailed = javascriptAtomic.map((unit, index) => atomicToLesson("javascript", unit, index + 1));
const pythonDetailed = pythonAtomic.map((unit, index) => atomicToLesson("python", unit, index + 1));

