export function findPath(id: string | undefined) { return languagePaths.find((path) => path.id === id) ?? languagePaths[0]; }
export function findLesson(path: LanguagePath, lessonId: string | undefined) { return path.lessons.find((lesson) => lesson.id === lessonId) ?? path.lessons[0]; }
